# payout.conf — defaults for the merchant payout file batch.
# Every value can be overridden from the environment (PAYOUT_*); the scheduler
# and the tests use that to point the batch at other directories.

TXN_FILE=${PAYOUT_TXN_FILE:-$PAYOUT_HOME/fixtures/txns-202610.tsv}
PARTNERS_FILE=${PAYOUT_PARTNERS_FILE:-$PAYOUT_HOME/conf/partners.conf}
WORK_DIR=${PAYOUT_WORK_DIR:-/var/tmp/payout}
OUT_DIR=${PAYOUT_OUT_DIR:-/var/lib/payout}

# Transfer CLI (vendor). Its spool directory comes from XFERQ_HOME.
XFERQ=${PAYOUT_XFERQ:-$PAYOUT_HOME/vendor/bin/xferq}
SEND_RETRIES=${PAYOUT_SEND_RETRIES:-2}

# Settlement file layout agreed with the partners (PAY-IF-03 rev.2)
FILE_PREFIX=HBP_SETTLE
FILE_EXT=csv
SENDER_ID=HBP
# Partners load at most this many detail rows per file.
MAX_ROWS_PER_FILE=20
# Partner intake runs on Windows hosts.
LINE_END=crlf
steps/20-build.sh:18:    name=$(settle_name "$p" "$date" "$i" "$parts")
xferq

